<script>
const C39={"0":"nnnwwnwnn","1":"wnnwnnnnw","2":"nnwwnnnnw","3":"wnwwnnnnn","4":"nnnwwnnnw","5":"wnnwwnnnn","6":"nnwwwnnnn","7":"nnnwnnwnw","8":"wnnwnnwnn","9":"nnwwnnwnn","A":"wnnnnwnnw","B":"nnwnnwnnw","C":"wnwnnwnnn","D":"nnnnwwnnw","E":"wnnnwwnnn","F":"nnwnwwnnn","G":"nnnnnwwnw","H":"wnnnnwwnn","I":"nnwnnwwnn","J":"nnnnwwwnn","K":"wnnnnnnww","L":"nnwnnnnww","M":"wnwnnnnwn","N":"nnnnwnnww","O":"wnnnwnnwn","P":"nnwnwnnwn","Q":"nnnnnnwww","R":"wnnnnnwwn","S":"nnwnnnwwn","T":"nnnnwnwwn","U":"wwnnnnnnw","V":"nwwnnnnnw","W":"wwwnnnnnn","X":"nwnnwnnnw","Y":"wwnnwnnnn","Z":"nwwnwnnnn","-":"nwnnnnwnw",".":"wwnnnnwnn"," ":"nwwnnnwnn","$":"nwnwnwnnn","/":"nwnwnnnwn","+":"nwnnnwnwn","%":"nnnwnwnwn","*":"nwnnwnwnn"};
function barcodeSvg(code){code=String(code).toUpperCase().replace(/[^0-9A-Z. $\/+%\-]/g,'-');let x=8,bars='';for(const ch of `*${code}*`){const p=C39[ch]||C39['-'];for(let i=0;i<p.length;i++){const w=p[i]==='w'?3:1;if(i%2===0)bars+=`<rect x="${x}" y="2" width="${w}" height="42"/>`;x+=w}x+=1}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${x+8} 46" preserveAspectRatio="none">${bars}</svg>`}
const esc=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));
document.querySelectorAll('.barcode-preview').forEach(svg=>svg.outerHTML=barcodeSvg(svg.dataset.code).replace('<svg ','<svg class="barcode-preview" '));
document.querySelectorAll('.label-print').forEach(btn=>btn.addEventListener('click',()=>{const w=window.open('','_blank','width=520,height=420');if(!w)return;w.document.write(`<!doctype html><html><head><title>Raf Etiketi</title><style>@page{size:70mm 40mm;margin:2mm}body{margin:0;font-family:Arial}.label{width:66mm;height:36mm;box-sizing:border-box;border:1px solid #111;padding:2mm;text-align:center;overflow:hidden}.loc{font-size:15pt;font-weight:900}.name{font-size:8pt;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.barcode{width:61mm;height:16mm;display:block;margin:1mm auto}.code{font:700 8pt monospace}.oem{font-size:7pt}</style></head><body><div class="label"><div class="loc">${esc(btn.dataset.location)}</div><div class="name">${esc(btn.dataset.name)}</div>${barcodeSvg(btn.dataset.code).replace('<svg ','<svg class="barcode" ')}<div class="code">${esc(btn.dataset.code)}</div><div class="oem">OEM: ${esc(btn.dataset.oem)}</div></div><script>onload=()=>{print();close()}<\/script></body></html>`);w.document.close()}));
</script>
